const TITLE_EXCLUDE = ['Product', 'Social Media', 'Account', 'Sales', 'Marketing'];
const TITLE_KEYWORDS = ['Manager', 'AI'];
const TITLE_MODE = 'any';
const LOCATION_KEYWORDS = ['Remote'];
const LOCATION_MODE = 'any';

const knownUrls = new Set(
  $('Read Jobs DB').all().map(function(item) {
    return (item.json.url || item.json.absolute_url || '').trim();
  })
);

const companies = $input.all().map(function(i) { return i.json; });
const matched = [];

function matchesAny(text, keywords) {
  const t = text.toLowerCase();
  return keywords.some(function(k) { return t.indexOf(k.toLowerCase()) !== -1; });
}

function matchesMode(text, keywords, mode) {
  if (!keywords.length) return true;
  const t = text.toLowerCase();
  const checks = keywords.map(function(k) { return t.indexOf(k.toLowerCase()) !== -1; });
  return mode === 'all' ? checks.every(Boolean) : checks.some(Boolean);
}

for (const c of companies) {
  const type = (c.Type || '').toLowerCase();
  const token = c.Token || '';
  const company = c.Company || '';

  let url = null;
  if (type.indexOf('greenhouse') !== -1) {
    url = 'https://boards-api.greenhouse.io/v1/boards/' + token + '/jobs?content=false';
  } else if (type.indexOf('ashby') !== -1) {
    url = 'https://api.ashbyhq.com/posting-api/job-board/' + token;
  }
  if (!url) continue;

  let jobs = [];
  try {
    const data = await this.helpers.httpRequest({
      method: 'GET',
      url: url,
      headers: { 'accept': 'application/json' },
      json: true
    });
    jobs = (data && data.jobs) || [];
  } catch (e) {
    continue;
  }

  for (const job of jobs) {
    const title = (job.title || '').trim();
    const jobUrl = (job.absolute_url || job.jobUrl || '').trim();
    const location = ((job.location && job.location.name) || job.workplaceType || '').trim();

    if (!jobUrl) continue;
    if (TITLE_EXCLUDE.length && matchesAny(title, TITLE_EXCLUDE)) continue;
    if (!matchesMode(title, TITLE_KEYWORDS, TITLE_MODE)) continue;
    if (!matchesMode(location, LOCATION_KEYWORDS, LOCATION_MODE)) continue;
    if (knownUrls.has(jobUrl)) continue;

    matched.push({
      title: title,
      url: jobUrl,
      location: location,
      company: company,
      updated_at: job.updated_at || '',
      first_published: job.first_published || ''
    });
  }
}

return [{ json: { matched: matched, hasNew: matched.length > 0 } }];

const result = $input.all()[0].json;
const jobs = result.matched || [];
let emailBody;
if (result.hasNew) {
  const lines = jobs.map(function(j) {
    return '<li>' + j.title + ' (' + j.company + ')<br>' + j.url + '</li>';
  });
  emailBody = '<p>' + jobs.length + ' new job opening(s) matching your criteria:</p><ul>' + lines.join('') + '</ul>';
} else {
  emailBody = '<p>No new job openings today matching your criteria.</p>';
}
return [{ json: { emailBody: emailBody, count: jobs.length, hasNew: result.hasNew, recipientEmail: 'YOUR_EMAIL' } }];
